// Builds a single-file version of a jacoto entry stylesheet.
// Usage: node tools/build-bundle.js jacoto_dark_malibu.css
// Output: jacoto_dark_malibu.bundle.css (same folder)
//
// - inlines every local @import (keeping its media condition)
// - keeps remote @imports at the top, as CSS requires
// - points the Open Sans fonts at res/*.woff2 with the .ttf as fallback
// - adds font-display: optional so a slow font never re-flows the page
const fs = require("fs");
const path = require("path");

const entry = process.argv[2] || "jacoto_dark_malibu.css";
const root = path.dirname(path.resolve(entry));
const read = (f) => fs.readFileSync(path.join(root, f), "utf8").replace(/^﻿/, "");

const remote = [];
const parts = [];
const importRe = /@import\s+url\(\s*['"]?([^'")]+)['"]?\s*\)\s*([^;]*);/g;

for (const m of read(entry).matchAll(importRe)) {
  const [, href, media] = m;
  if (/^https?:/.test(href)) { remote.push(m[0]); continue; }
  let css = read(href);
  const dir = path.posix.dirname(href);
  // fonts: woff2 first, ttf fallback, paths made relative to the bundle
  css = css.replace(/url\(\s*['"]?(OpenSans-[\w-]+)\.ttf['"]?\s*\)/g, (_, name) =>
    `url('${dir}/${name}.woff2') format('woff2'), url('${dir}/${name}.ttf') format('truetype')`);
  css = css.replace(/@font-face\s*\{/g, "@font-face {font-display: optional;");
  const label = `/* ---- ${href}${media.trim() ? " (" + media.trim() + ")" : ""} ---- */\n`;
  parts.push(media.trim() ? `${label}@media ${media.trim()} {\n${css}\n}` : label + css);
}

const out = entry.replace(/\.css$/, ".bundle.css");
const header = `/* Generated by tools/build-bundle.js from ${entry} - edit the sources, then rebuild. */\n`;
fs.writeFileSync(path.join(root, out), header + remote.join("\n") + "\n\n" + parts.join("\n\n") + "\n");
console.log(`${out}: ${fs.statSync(path.join(root, out)).size} bytes, ${parts.length} files inlined, ${remote.length} remote import(s) kept`);
